import{_ as t,o as a,c as o,ai as i}from"./chunks/framework.Cg3BiOJh.js";const u=JSON.parse('{"title":"Install VPP","description":"Install the VPP v1.5 plugin, connect the remote MCP server, or use the portable Agent Skill.","frontmatter":{"title":"Install VPP","description":"Install the VPP v1.5 plugin, connect the remote MCP server, or use the portable Agent Skill."},"headers":[],"relativePath":"install/index.md","filePath":"install/index.md","lastUpdated":1786775408000}'),s={name:"install/index.md"};function n(r,e,l,p,c,d){return a(),o("div",null,[...e[0]||(e[0]=[i(`<p>Choose the complete plugin when your host supports plugins. It keeps the portable <code>viable-prompt-protocol</code> Agent Skill, production MCP connection, generated v1.5 references, and offline fallback together as one versioned install.</p><p>The public runtime is anonymous and requires no VPP account or API key.</p><h2 id="codex-and-chatgpt-desktop" tabindex="-1">Codex and ChatGPT desktop <a class="header-anchor" href="#codex-and-chatgpt-desktop" aria-label="Permalink to &quot;Codex and ChatGPT desktop&quot;">​</a></h2><p>Until VPP is available in the public Plugins Directory, add the repository marketplace and install the plugin:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> marketplace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cbassuarez/viable-prompt-protocol</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> viable-prompt-protocol@viable-prompt-protocol</span></span></code></pre></div><p>Restart the ChatGPT desktop app or begin a new Codex session so the skill and MCP tools are discovered. Start with a VPP command on line 1, such as <code>!&lt;g&gt;</code>, or explicitly invoke <code>$viable-prompt-protocol</code>.</p><p>This repository install is the same plugin package being prepared for OpenAI&#39;s public directory. After publication, users will be able to install it directly from the shared Plugins Directory in ChatGPT or Codex.</p><h2 id="download-the-portable-bundle" tabindex="-1">Download the portable bundle <a class="header-anchor" href="#download-the-portable-bundle" aria-label="Permalink to &quot;Download the portable bundle&quot;">​</a></h2><ul><li><a href="/downloads/viable-prompt-protocol-plugin-1.0.0.zip">Download the complete plugin 1.0.0</a> (<a href="/downloads/viable-prompt-protocol-plugin-1.0.0.zip.sha256.txt">SHA-256</a>)</li><li><a href="/downloads/viable-prompt-protocol-skill-1.0.0.zip">Download the standalone Agent Skill 1.0.0</a> (<a href="/downloads/viable-prompt-protocol-skill-1.0.0.zip.sha256.txt">SHA-256</a>)</li></ul><p>The complete archive contains the same plugin directory used by the repository marketplace. Use it for local inspection, a manual install, or distribution to another plugin-compatible host. The standalone archive is the portable skill tree for Agent Skills hosts and submission systems that accept a skill bundle directly.</p><p>Both include <code>scripts/vpp.mjs</code>, a deterministic offline fallback for hosts that cannot reach the remote service. Verify a downloaded artifact with its adjacent SHA-256 file when your installation process requires supply-chain verification.</p><h2 id="connect-the-remote-mcp-server" tabindex="-1">Connect the remote MCP server <a class="header-anchor" href="#connect-the-remote-mcp-server" aria-label="Permalink to &quot;Connect the remote MCP server&quot;">​</a></h2><p>Hosts with Streamable HTTP MCP support can connect directly:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://mcp.viableprompt.org/mcp</span></span></code></pre></div><p>In ChatGPT developer mode, open Plugins, select the plus button, create a public MCP connection, and enter the complete URL above. Choose no authentication. The service exposes four read-only computation tools, five immutable v1.5 references, and the <code>start-vpp</code> prompt.</p><p>You can confirm that the production service is available at <a href="https://mcp.viableprompt.org/healthz" target="_blank" rel="noreferrer"><code>/healthz</code></a>. The MCP endpoint itself expects MCP requests; opening <code>/mcp</code> as an ordinary web page is not a functional test.</p><h2 id="use-the-json-or-openapi-api" tabindex="-1">Use the JSON or OpenAPI API <a class="header-anchor" href="#use-the-json-or-openapi-api" aria-label="Permalink to &quot;Use the JSON or OpenAPI API&quot;">​</a></h2><p>Cloud apps and hosts without remote MCP can use the equivalent stateless operations:</p><ul><li><code>POST https://mcp.viableprompt.org/api/v1/prepare-turn</code></li><li><code>POST https://mcp.viableprompt.org/api/v1/format-response</code></li><li><code>POST https://mcp.viableprompt.org/api/v1/validate-exchange</code></li><li><code>POST https://mcp.viableprompt.org/api/v1/validate-transcript</code></li><li><code>GET https://mcp.viableprompt.org/api/v1/openapi.json</code></li></ul><p>Carry the returned <code>state</code> to the next exchange. Omit it only for a genuinely new conversation.</p><h2 id="what-the-runtime-does-with-your-content" tabindex="-1">What the runtime does with your content <a class="header-anchor" href="#what-the-runtime-does-with-your-content" aria-label="Permalink to &quot;What the runtime does with your content&quot;">​</a></h2><p>The service receives the command, response, state, or transcript supplied to the selected operation and returns a deterministic structural result. It does not create an account, persist conversation state, or enable application-level request-body logging. Do not send secrets or personal data that are unnecessary for validation. Read the full <a href="/privacy/">privacy policy</a> before using the public endpoint with sensitive workflows.</p><p><a id="secondary-methods"></a></p><h2 id="secondary-methods-—-reduced-assurance" tabindex="-1">Secondary methods — reduced assurance <a class="header-anchor" href="#secondary-methods-—-reduced-assurance" aria-label="Permalink to &quot;Secondary methods — reduced assurance&quot;">​</a></h2><p>Read the <a href="/spec/">normative v1.5 specification</a> when implementing another host adapter. Only when the host cannot install a skill, call MCP, or use the JSON operations should you use the <a href="/custom-instructions/">custom-instructions fallback</a>. That route is reduced assurance because the model must maintain and repair its own structural state.</p><p>Need help choosing an installation route? See <a href="/support/">Support</a>.</p>`,26)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
